'use strict';
const $=id=>document.getElementById(id);let calc=new Calculator(),mode='calculate',converted=false;
function render(message,error=false){
 const converter=mode==='convert',target=+$('targetBase').value;const output=converter&&converted?Examples.format(calc.value(),target,calc.width):calc.entry;
 $('display').value=output;$('display').inputMode=calc.base===16?'text':'numeric';$('display').classList.toggle('binary',output.length>10);$('expression').textContent=converter?(converted?`${calc.entry} (base ${calc.base}) → base ${target}`:'Enter a number, then press Convert'):calc.expression;$('displayLabel').textContent=converter&&converted?'CONVERTED ANSWER':calc.last&&calc.fresh?'ANSWER':'ENTER A NUMBER';$('range').textContent=`${calc.width}-bit · ${converter&&converted?target:calc.base===10?'Decimal':calc.base===16?'Hex':'Binary'}${converter&&converted?' base':''}`;
 $('width').value=calc.width;$('inputBase').value=calc.base;$('carry').checked=calc.carry;$('carry').disabled=converter;$('targetControl').hidden=!converter;$('inputFormatLabel').textContent=converter?'Convert from':'Number format';$('hexKeys').hidden=calc.base!==16;document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===mode)));document.querySelectorAll('[data-digit]').forEach(b=>b.disabled=parseInt(b.dataset.digit,16)>=calc.base);document.querySelectorAll('[data-op],[data-unary]').forEach(b=>b.disabled=converter);
 const equals=document.querySelector('[data-action="equals"]');equals.innerHTML=converter?'→<small>Convert</small>':'=<small>Equals</small>';equals.setAttribute('aria-label',converter?'Convert':'Equals');
 let hint=converter?(converted?'Conversion complete. Change the target format or enter a new number.':'Select the source and target formats. Enter your number and press Convert.'):calc.op?(calc.fresh?'Now enter the second number.':'Press Equals to see the answer.'):'Enter a number, then choose an operation.';
 if(!converter&&calc.last&&calc.fresh)hint=calc.last.explanation||(calc.last.overflow?'The magnitude fits unsigned, but exceeds the positive signed range.':'Done. Enter a number to start a new calculation.');$('message').textContent=message||hint;$('message').classList.toggle('error',error);
 const v=calc.last;$('detailStatus').textContent=v?'Flags from the most recent completed operation.':'Run a calculation to see flags and instructions. Conversion changes the representation only.';$('flags').replaceChildren();$('steps').replaceChildren();$('assembly').textContent=v?v.code:'; No arithmetic operation yet';$('flagNote').textContent=v?v.note:'';if(v){for(const [k,val]of Object.entries(v.flags)){const el=document.createElement('div');el.className='flag'+(val===1?' set':'');el.textContent={S:'Sign',Z:'Zero',AC:'Aux. carry',P:'Parity',CY:'Carry / borrow'}[k];const b=document.createElement('b');b.textContent=val===null?'—':val;el.append(b);$('flags').append(el);}for(const s of v.steps){const li=document.createElement('li');li.textContent=s;$('steps').append(li);}}
}
function act(fn){try{fn();render();}catch(e){render(e.message,true);}}
function inputDigit(d){if(parseInt(d,16)>=calc.base)return;if(converted){calc.entry='0';calc.fresh=false;converted=false;}calc.digit(d);}
function action(name){if(name==='help'){$('helpDialog').showModal();return;}act(()=>{if(name==='clear'){calc.clear();calc.carry=false;converted=false;}if(name==='sign'){calc.sign();converted=false;}if(name==='back'){calc.back();converted=false;}if(name==='equals'){if(mode==='convert')converted=true;else calc.equals();}});}
document.querySelectorAll('[data-digit]').forEach(b=>b.addEventListener('click',()=>act(()=>inputDigit(b.dataset.digit))));document.querySelectorAll('[data-op]').forEach(b=>b.addEventListener('click',()=>act(()=>calc.choose(b.dataset.op))));document.querySelectorAll('[data-unary]').forEach(b=>b.addEventListener('click',()=>act(()=>calc.unary(b.dataset.unary))));document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>action(b.dataset.action)));
document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>act(()=>{mode=b.dataset.mode;converted=false;calc.op=null;calc.left=null;calc.fresh=false;calc.last=null;calc.expression='Ready when you are';})));
 $('inputBase').addEventListener('change',()=>act(()=>{calc.setBase(+$('inputBase').value);converted=false;}));$('targetBase').addEventListener('change',()=>render());$('width').addEventListener('change',()=>act(()=>{calc.setWidth(+$('width').value);converted=false;}));$('carry').addEventListener('change',()=>{calc.carry=$('carry').checked;render();});
Examples.examples.forEach((ex,i)=>{const option=document.createElement('option');option.value=i;option.textContent=ex.label;$('exampleSelect').append(option);});
$('runExample').addEventListener('click',()=>act(()=>{const ex=Examples.examples[+$('exampleSelect').value],run=Examples.run(ex);calc=run.calculator;mode=ex.convert?'convert':'calculate';converted=!!ex.convert;if(ex.convert)$('targetBase').value=ex.convert;$('exampleStatus').textContent=`${run.passed?'PASS ✓':'FAIL ✕'} Expected ${ex.expected}; got ${run.result}${ex.convert?'':'; CY '+(calc.last.flags.CY===null?'unchanged':calc.last.flags.CY)}.`;$('exampleStatus').className=run.passed?'pass':'fail';}));
 $('testAll').addEventListener('click',()=>{const results=Examples.examples.map(ex=>{try{return {...Examples.run(ex),name:ex.name};}catch(e){return {passed:false,name:ex.name};}}),failed=results.filter(r=>!r.passed);$('exampleStatus').textContent=failed.length?`Failed: ${failed.map(r=>r.name).join(', ')}`:`PASS ✓ All ${results.length} examples match their expected answers and flags.`;$('exampleStatus').className=failed.length?'fail':'pass';});
document.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey||($('helpDialog').open||$('detailsDialog').open)||['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(e.key==='Enter'&&['BUTTON','SUMMARY'].includes(e.target.tagName))return;let handled=true;if(/^[0-9a-f]$/i.test(e.key))act(()=>inputDigit(e.key.toUpperCase()));else if(mode==='calculate'&&e.key==='+')act(()=>calc.choose('ADD'));else if(mode==='calculate'&&e.key==='-')act(()=>calc.choose('SUB'));else if(['Enter','='].includes(e.key))action('equals');else if(e.key==='Backspace')action('back');else if(e.key==='Escape')action('clear');else handled=false;if(handled)e.preventDefault();});$('display').addEventListener('focus',()=> $('display').select());
$('display').addEventListener('input',()=>{const s=$('display').value.trim().toUpperCase(),pattern=calc.base===16?/^[0-9A-F]*$/:calc.base===2?/^[01]*$/:/^-?\d*$/;try{if(!pattern.test(s))throw Error('Use digits valid for the selected number format.');const n=s===''||s==='-'?0:parseInt(s,calc.base);if(n>2**calc.width-1||n<-(2**(calc.width-1)))throw Error('This value is outside the selected number size. Choose 16-bit for larger numbers.');calc.entry=s;calc.fresh=false;calc.last=null;converted=false;render();}catch(e){render(e.message,true);}});
$('display').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();action('equals');}else if(mode==='calculate'&&(e.key==='+'||(e.key==='-'&&calc.entry!==''&&calc.entry!=='0'))){e.preventDefault();act(()=>calc.choose(e.key==='+'?'ADD':'SUB'));$('display').select();}});
$('display').addEventListener('blur',()=>{if(calc.entry===''||calc.entry==='-'){calc.entry='0';render();}});
$('showDetails').addEventListener('click',()=>$('detailsDialog').showModal());$('closeDetails').addEventListener('click',()=>$('detailsDialog').close());
$('closeHelp').addEventListener('click',()=>$('helpDialog').close());render();
